const links = phi.query("a", { fields: ["href", "class"], limit: 400 });
const items = links.items.map(i => ({ t: (i.text||"").replace(/\s+/g," ").trim(), h: i.href }));
const hood = items.filter(x => /neighborhood-maps\/brooklyn\//i.test(x.h));
const txt = phi.text();
// find the section boundaries
const start = txt.indexOf("Brooklyn neighborhood maps", 200);
const end = txt.indexOf("Bronx", start) > 0 ? txt.indexOf("Bronx", start) : txt.length;
return { total: links.total, hoodCount: hood.length, hoodSample: hood.slice(0,5), hoodLast: hood.slice(-5), textLen: txt.length, section: txt.slice(start, start+8000).length, tail: txt.slice(start).slice(-1200) };

const r = phi.goto("https://new.mta.info/maps/neighborhood-maps/brooklyn");
phi.waitForNetworkIdle({ timeoutMs: 8000 });
const txt = phi.text();
const start = txt.indexOf("Brooklyn neighborhood maps", 200);
const items = phi.query("main a, main li, ul a, ol a", { fields: ["href", "class"], limit: 400 });
const sample = items.items.slice(0, 15).map(i => ({ t: (i.text||"").replace(/\s+/g," ").trim().slice(0,60), h: i.href, c: i.class }));
return { url: r.url, title: r.title, total: items.total, sample, textLen: txt.length, head: txt.slice(start, start+600) };

const obs = phi.observe({ maxElements: 80 });
const struct = phi.js(() => {
  const main = document.querySelector("main") || document.body;
  const lis = Array.from(document.querySelectorAll("li"));
  const sample = lis.slice(0, 6).map(li => ({ tag: li.tagName, cls: li.className, html: li.outerHTML.slice(0, 300) }));
  // count li with station names
  const st = lis.filter(li => /\(([A-Z0-9])\)/.test(li.textContent || ""));
  return { liTotal: lis.length, stationLis: st.length, sample, firstStationHTML: st[0] ? st[0].outerHTML.slice(0,600) : null, mainCls: main.className, scripts: Array.from(document.querySelectorAll("script[src]")).length };
});
return { url: obs.url, nodes: obs.nodes.slice(0, 40).map(n => ({ r: n.ref, role: n.role, name: (n.name||"").slice(0,60) })), total: obs.total, struct };

const data = phi.js(() => {
  const anchors = Array.from(document.querySelectorAll("a[href]"));
  const hits = anchors.map(a => ({ t: (a.textContent||"").replace(/\s+/g," ").trim(), h: a.getAttribute("href"), abs: a.href }))
    .filter(x => /neighborhood-maps/i.test(x.h) || /neighborhood-maps/i.test(x.abs))
    .filter(x => !/\/brooklyn\/?$/i.test(x.abs) && !/\/bronx\/?$/i.test(x.abs) && !/\/manhattan\/?$/i.test(x.abs) && !/\/queens\/?$/i.test(x.abs) && !/\/staten-island\/?$/i.test(x.abs));
  return { anchorTotal: anchors.length, hitsCount: hits.length, first: hits.slice(0,5), last: hits.slice(-5) };
});
const sample = phi.query("main a", { fields: ["href"], limit: 5 });
return { data, sample };

const info = phi.js(() => {
  const main = document.querySelector("main") || document.body;
  const all = Array.from(main.querySelectorAll("a"));
  const st = all.filter(a => /\(([A-Z0-9])\)/.test(a.textContent || ""));
  const first = st.slice(0, 3).map(a => a.outerHTML.slice(0, 500));
  // maybe divs with data attributes
  const divs = Array.from(main.querySelectorAll("[data-url],[data-href],[onclick]")).slice(0,3).map(d => d.outerHTML.slice(0,300));
  const mainHTML = main.innerHTML.length;
  const idx = main.innerHTML.indexOf("4 Av-9 St");
  return { anchorCount: all.length, stationAnchors: st.length, first, divs, mainHTML, snippet: main.innerHTML.slice(Math.max(0,idx-400), idx+400) };
});
return info;

const list = phi.js(() => {
  const main = document.querySelector("main") || document.body;
  const all = Array.from(main.querySelectorAll("a[href^='/document/']"));
  return all.map(a => ({
    name: (a.querySelector(".link-title")?.textContent || a.textContent || "").replace(/\s+/g," ").trim(),
    href: a.getAttribute("href")
  })).filter(x => x.name);
});
phi.keep("brooklyn_www", list);
const nav = phi.goto("https://new.mta.info/maps/neighborhood-maps/brooklyn");
return { count: list.length, first5: list.slice(0,5), last5: list.slice(-5), nav };

const a = phi.goto("https://new.mta.info/maps/neighborhood-maps");
const b = phi.goto("https://new.mta.info/");
return { a: { url: a.url, title: a.title }, b: { url: b.url, title: b.title } };

const idx = phi.goto("https://www.mta.info/maps/neighborhood-maps");
const links = phi.query("a", { fields: ["href"], limit: 400 });
const boro = links.items.filter(x => /neighborhood-maps/.test(x.href || "")).map(x => x.href);
const text = phi.text();
const i = text.indexOf("Brooklyn");
const list = phi.recall("brooklyn_www");
const bases = {};
for (const it of list) {
  const base = it.name.replace(/\s*\([^)]*\)/g, "").trim();
  bases[base] = (bases[base] || 0) + 1;
}
const uniqueBases = Object.keys(bases);
phi.keep("brooklyn_summary", { totalEntries: list.length, uniqueStations: uniqueBases.length, stations: uniqueBases, sample: list.slice(0, 8) });
return { idxUrl: idx.url, idxTitle: idx.title, boroLinks: [...new Set(boro)], textAround: text.slice(Math.max(0, i - 200), i + 600), totalEntries: list.length, uniqueStations: uniqueBases.length, firstUnique: uniqueBases.slice(0, 10) };

const nav = phi.goto("https://new.mta.info/maps/neighborhood-maps/brooklyn");
const page = { url: nav.url, title: nav.title };
const anchors = phi.query("a[href^='/document/']", { limit: 300 });
const heading = phi.query("h1", { limit: 2 });
const list = phi.recall("brooklyn_www");
const ts = phi.recall("brooklyn_summary");
phi.keep("final_answer_core", {
  redirect: "new.mta.info now serves the same pages on www.mta.info",
  finalUrl: nav.url,
  pageTitle: nav.title,
  h1: heading.items.map(h => h.text),
  mapEntriesOnPage: anchors.total,
  keptEntries: list.length,
  uniqueStations: ts.uniqueStations,
  stations: ts.stations,
});
return { page, h1: heading.items.map(h => h.text), anchorsOnPage: anchors.total, first3: anchors.items.slice(0,3), keptEntries: list.length, uniqueStations: ts.uniqueStations };

const list = phi.recall("brooklyn_www");
const names = list.map(x => x.name);
const compact = names.join(" | ");
phi.keep("brooklyn_list_names", { count: names.length, names: compact + "" , firstHref: list[0].href});
const sum = names.join(" | ").length;
return { count: names.length, chars: sum, last5: names.slice(-5), first5: names.slice(0,5) };

const kept = phi.recall("brooklyn_list_names");
const names = kept.names.split(" | ");
const half = Math.ceil(names.length / 2);
return { count: names.length, part1: names.slice(0, half).join(" | "),
         part2: names.slice(half).join(" | ") };

const vis = phi.js(() => {
  const as = Array.from(document.querySelectorAll("a[href*='/document/']"));
  const shown = as.filter(a => a.offsetParent !== null || a.getClientRects().length > 0);
  const h1 = document.querySelector("h1")?.textContent.trim();
  const counts = document.querySelectorAll("a[href*='/document/']").length;
  return {
    h1,
    totalAnchors: as.length,
    renderedAnchors: shown.length,
    sampleRendered: shown.slice(0, 5).map(a => a.textContent.trim()),
    lastRendered: shown.slice(-3).map(a => a.textContent.trim()),
    pageHeadingContext: document.body.innerText.split("\n").slice(0, 8)
  };
});
const names = phi.recall("brooklyn_list_names");
return { url: location.href, vis, listCount: names.count };

const q = phi.query("a[href*='/document/']", { fields: ["href"], limit: 5 });
const obs = phi.observe({ viewportOnly: true, maxElements: 30 });
const heading = phi.query("h1", { limit: 1 });
const kept = phi.recall("final_answer_core");
return { url: q.total, firstHrefs: q.items.map(i => i.href), h1: heading.items[0]?.text, visNodes: obs.nodes.slice(0, 12).map(n => n.role + ":" + (n.name||"")), core: kept };
